package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.storage.*;
import net.minecraft.util.ProblemReporter;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.*;
import thaumcraft.golems.*;
import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class LogisticsProbe {
    public static final BlockPos Q=GolemProbe.Q;static ServerPlayer p;static int ticks;static boolean done;
    public static ItemStack parcel(int count){var s=new ItemStack(Items.DIAMOND,count);s.set(DataComponents.CUSTOM_NAME,Component.literal("Requested parcel"));return s;}
    public static void filters(ServerPlayer p,SealEntity s){p.setPos(s.getBlockPos().getX()+.5,s.getBlockPos().getY(),s.getBlockPos().getZ()+2.5);s.sample(0,parcel(1));s.sample(8,new ItemStack(Items.EMERALD));check(s.matches(parcel(1))&&s.matches(new ItemStack(Items.EMERALD))&&!s.matches(new ItemStack(Items.DIAMOND)),"Nine exact samples lost components");s.exact=false;check(s.matches(new ItemStack(Items.DIAMOND)),"Item-only matching failed");if(s.kind()!=SealKind.STOCK){s.blacklist=true;check(!s.matches(new ItemStack(Items.DIAMOND))&&!s.matches(new ItemStack(Items.EMERALD))&&s.matches(new ItemStack(Items.GOLD_INGOT)),"Multisample exclusion failed");}s.blacklist=false;s.exact=true;var menu=new SealMenu(101,p.getInventory(),s);menu.clicked(8,0,net.minecraft.world.inventory.ContainerInput.PICKUP,p);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.EMERALD,11));check(menu.clickMenuButton(p,4)&&s.sample(8).is(Items.EMERALD)&&p.getMainHandItem().getCount()==11,"Ghost filter consumed sample");menu.broadcastChanges();check(menu.getSlot(8).getItem().is(Items.EMERALD)&&!menu.getSlot(8).mayPickup(p),"Ghost sample can be withdrawn");Thaumcraft.LOGGER.info("LOGISTICS_FILTERS_OK: nine samples, exact/item-only/exclusion and locked ghost slots");}
    @SubscribeEvent public static void start(ServerStartedEvent e){var mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("logistics-write")&&!mode.equals("logistics-read"))return;var l=e.getServer().overworld();l.setChunkForced(12,0,true);l.setChunkForced(11,0,true);p=new ServerPlayer(e.getServer(),l,new GameProfile(GolemProbe.OWNER,"LogisticsProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(Component c,boolean b){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};knowledge(p);
        if(mode.equals("logistics-read")){var s=(SealEntity)l.getBlockEntity(Q.west(5));check(s!=null&&s.kind()==SealKind.STOCK&&s.sample(8).is(Items.EMERALD)&&s.amounts[0]==23&&s.amounts[8]==11&&s.exact,"New stock settings lost at restart");return;}
        var legacy=(SealEntity)l.getBlockEntity(Q.east(7));check(legacy!=null&&legacy.kind()==SealKind.FILL&&legacy.filter.is(Items.DIAMOND)&&legacy.exact&&legacy.sample(8).isEmpty(),"port.20 seal migration failed");Thaumcraft.LOGGER.info("LOGISTICS_PORT20_OK: actual port.20 seal and worker loaded without loss");
        var advanced=GolemProbe.seal(p,SealKind.EMPTY_ADVANCED,Q.south(3));filters(p,advanced);var stock=GolemClient.chestSeal(p,SealKind.STOCK,Q.west(4));filters(p,stock);stock.amounts[0]=23;stock.amounts[8]=11;stock.setChanged();var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(stock.support());chest.setItem(0,parcel(7));check(stock.wanted(parcel(1))==16,"Stock did not subtract existing inventory");stock.sample(1,parcel(1));stock.amounts[1]=9;check(stock.wanted(parcel(1))==16,"Duplicate filter added goals instead of taking maximum");
        var provider=GolemClient.chestSeal(p,SealKind.PROVIDER,Q.north(5));var supply=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(provider.support());supply.setItem(0,parcel(64));var g=new WorkerGolem(GolemContent.GOLEM.get(),l);g.configure(p,GolemDesign.BASIC,Q.west(2),0);provider.serverTick();stock.serverTick();var plan=GolemLogistics.find(l,g,stock);check(plan!=null&&plan.requested().getCount()==16&&supply.getItem(0).getCount()==64,"Planning moved items or requested beyond deficit");
        g.cargo.setItem(0,parcel(16));var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,p.registryAccess());out.putLong("delivery",stock.getBlockPos().asLong());out.store("requested",ItemStack.CODEC,parcel(1));g.saveWithoutId(out);var copy=new WorkerGolem(GolemContent.GOLEM.get(),l);copy.load(TagValueInput.create(ProblemReporter.DISCARDING,p.registryAccess(),out.buildResult()));check(copy.delivery().equals(stock.getBlockPos())&&ItemStack.matches(copy.requested(),parcel(1))&&copy.cargo.getItem(0).getCount()==16,"Delivery snapshot lost physical cargo/route");copy.setCustomName(Component.literal("Persistent delivery"));l.setBlockAndUpdate(copy.blockPosition().below(),Blocks.STONE.defaultBlockState());l.addFreshEntity(copy);Thaumcraft.LOGGER.info("LOGISTICS_PLAN_OK: bounded physical request, overlap goal and saved delivery snapshot");}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){var mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("logistics-write")&&!mode.equals("logistics-read")||done||++ticks<40)return;if(mode.equals("logistics-write")){check(e.server().overworld().getEntitiesOfClass(WorkerGolem.class,new net.minecraft.world.phys.AABB(Q).inflate(16)).stream().anyMatch(g->g.hasCustomName()&&g.getCustomName().getString().equals("Persistent porter")&&g.getHealth()==7&&g.cargo.getItem(0).getCount()==17),"Actual port.20 worker lost data");}if(mode.equals("logistics-read")){var l=e.server().overworld();check(l.getEntitiesOfClass(WorkerGolem.class,new net.minecraft.world.phys.AABB(Q).inflate(16)).stream().anyMatch(g->g.hasCustomName()&&g.getCustomName().getString().equals("Persistent delivery")&&g.delivery().equals(Q.west(5))&&g.cargo.getItem(0).getCount()==16),"Native restart lost delivery route/cargo");Thaumcraft.LOGGER.info("LOGISTICS_RESTART_OK: nine filters, exact quantities and physical delivery cargo/route");}else Thaumcraft.LOGGER.info("LOGISTICS_WRITE_OK: new filter settings and in-flight delivery saved");done=true;e.server().halt(false);}
}
